namespace sv_8da330a0d4134c4ab66f4535a3caa15e.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service — in Blazor Server each circuit (user) gets its own instance,
/// so one user's theme change never leaks to another user.
/// </summary>
public class ThemeService
{
    private Theme _theme = Theme.System;
    private string _accentColor = "#0d6efd";

    public Theme CurrentTheme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Fired whenever theme or accent color changes.
    /// Every subscribing component calls StateHasChanged in its handler.
    /// </summary>
    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}

@*
    Interactive island that lives in the static MainLayout.
    Because it has its own @rendermode, it joins the circuit and can
    subscribe to the scoped ThemeService — reacting to changes made
    from ANY interactive component on ANY page.
*@
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<span class="badge rounded-pill"
      style="background-color: @ThemeService.AccentColor; color: white;">
    @ThemeService.CurrentTheme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged() => InvokeAsync(StateHasChanged);

    public void Dispose() => ThemeService.OnChange -= HandleThemeChanged;
}

@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<div class="d-flex align-items-center gap-2">
    <label class="form-label mb-0">Theme:</label>
    @foreach (var theme in Enum.GetValues<Theme>())
    {
        <button class="btn btn-sm @(theme == ThemeService.CurrentTheme ? "btn-primary" : "btn-outline-secondary")"
                @onclick="() => ThemeService.CurrentTheme = theme">
            @theme
        </button>
    }
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged() => InvokeAsync(StateHasChanged);

    public void Dispose() => ThemeService.OnChange -= HandleThemeChanged;
}

@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<PageTitle>User Preferences</PageTitle>

<h3>User Preferences</h3>

<div class="card mt-3" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>
        <div class="btn-group mb-3" role="group">
            @foreach (var theme in Enum.GetValues<Theme>())
            {
                <button type="button"
                        class="btn @(theme == ThemeService.CurrentTheme ? "btn-primary" : "btn-outline-primary")"
                        @onclick="() => ThemeService.CurrentTheme = theme">
                    @theme
                </button>
            }
        </div>

        <h5 class="card-title">Accent Color</h5>
        <input type="color"
               class="form-control form-control-color mb-3"
               value="@ThemeService.AccentColor"
               @onchange="OnAccentChanged" />

        <div class="alert alert-info mb-0">
            Current: <strong>@ThemeService.CurrentTheme</strong> /
            <span style="color: @ThemeService.AccentColor;">@ThemeService.AccentColor</span>
        </div>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        ThemeService.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    private void HandleThemeChanged() => InvokeAsync(StateHasChanged);

    public void Dispose() => ThemeService.OnChange -= HandleThemeChanged;
}

